<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;

trait ClientIdentityRelyingPartyAccessor
{
    private ?ClientIdentityRelyingPartyVO $_relyingParty = null;
    public function getRelyingParty(): ?RelyingPartyRef
    {
        return $this->_relyingParty?->value();
    }
    public function relyingParty(): ?ClientIdentityRelyingPartyVO
    {
        return $this->_relyingParty;
    }
    public function isRelyingPartyChanged(?self $original = null): bool
    {
        return null !== $this->_relyingParty && !$this->_relyingParty->equals($original?->_relyingParty);
    }
    public function withRelyingParty(ClientIdentityRelyingPartyVO|RelyingPartyRef|null $relyingParty): self
    {
        $copy = clone $this;
        $copy->_relyingParty = ClientIdentityRelyingPartyVO::from($relyingParty);
        return $copy;
    }
}
